<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class Stall extends Model { use HasFactory; protected $fillable = ['user_id', 'name', 'location', 'status']; public function user() { return$this->belongsTo(User::class); } public function foodItems() { return $this->hasMany(FoodItem::class); } public function orders() { return$this->hasMany(Order::class); } }